"""Idempotent synthetic demo seed. Everything is generated by code; nothing is a hand-edited DB dump.

All runs are labelled ``synthetic_demo`` (scripted + seeded fault injection). Calibration labels are
``synthetic_fixture`` (author-written) and annotation rows are ``synthetic_demo`` - never "human".
"""

from __future__ import annotations

import logging
from typing import Any

from evalcore.calibration import AdmissionPolicy
from evalcore.distill import distill_case
from evalcore.judge import JudgeConfig
from evalcore.models import Case
from sqlalchemy import func, select
from sqlalchemy.orm import Session

from .models import (
    CalibrationItem,
    CalibrationRun,
    CalibrationSet,
    Comparison,
    DistilledCandidate,
    EvalCase,
    HumanAnnotation,
    Run,
    Sample,
)
from .models import (
    JudgeConfig as JudgeRow,
)
from .services import catalog, comparisons, judges, runs

log = logging.getLogger("ars.seed")
SEED = 20260601
SAMPLES = 3
DATASETS = ["support/v1", "support/v2", "research/v1", "coding/v1", "redteam/v1"]
STRICT = ("synthetic strict keyword judge", "keyword-strict-v1", {"strictness": 1.0, "check_forbidden": True})
LENIENT = ("synthetic lenient keyword judge", "keyword-lenient-v0", {"strictness": 0.34, "check_forbidden": False})


def _judge(s: Session, spec: tuple[str, str, dict[str, Any]], rubric_version: str = "r1") -> JudgeRow:
    name, model, params = spec
    cfg = JudgeConfig(backend="heuristic", model=model, rubric_version=rubric_version)
    return catalog.sync_judge(
        s,
        name + ("" if rubric_version == "r1" else f" ({rubric_version})"),
        "heuristic",
        model,
        cfg,
        params,
        "Deterministic offline stand-in judge. Calibrated like any other judge; it may fail.",
    )


def seed_catalog(s: Session) -> dict[str, Any]:
    from demo_agents import VERSIONS

    for agent, versions in VERSIONS.items():
        for v in versions:
            catalog.sync_agent_version(
                s,
                f"{agent}:{v}",
                role="baseline" if v == "v1" else "candidate",
                notes=("Frozen. See PINS.md." if v == "v1" else "Candidate. See PINS.md for the change log."),
            )
    dvs = {p: catalog.sync_dataset(s, f"datasets/{p}.yaml") for p in DATASETS}
    cset = catalog.sync_calibration_set(s, "datasets/calibration/v1.yaml")
    return {"datasets": dvs, "cset": cset}


def seed_calibration(s: Session, cset: CalibrationSet) -> tuple[JudgeRow, JudgeRow, JudgeRow]:
    strict, lenient, strict_r2 = _judge(s, STRICT), _judge(s, LENIENT), _judge(s, STRICT, "r2")
    if (s.scalar(select(func.count(CalibrationRun.id))) or 0) == 0:
        # history: an early partial attempt (too few items), a failed lenient judge, then the admitted strict judge
        judges.calibrate(s, strict, cset, AdmissionPolicy(), limit=24)
        judges.calibrate(s, lenient, cset, AdmissionPolicy())
        judges.calibrate(s, strict, cset, AdmissionPolicy())
    return strict, lenient, strict_r2


def seed_annotations(s: Session, cset: CalibrationSet) -> None:
    if (s.scalar(select(func.count(HumanAnnotation.id))) or 0) > 0:
        return
    items = list(
        s.scalars(
            select(CalibrationItem).where(CalibrationItem.set_id == cset.id).order_by(CalibrationItem.item_id).limit(24)
        )
    )
    flip = {items[2].item_id, items[9].item_id, items[17].item_id}  # three deliberate disagreements
    for it in items:
        s.add(
            HumanAnnotation(
                item_pk=it.id,
                annotator="demo-annotator-a",
                label=it.reference_label,
                source="synthetic_demo",
                note="synthetic demo annotation",
            )
        )
        s.add(
            HumanAnnotation(
                item_pk=it.id,
                annotator="demo-annotator-b",
                label=(not it.reference_label) if it.item_id in flip else it.reference_label,
                source="synthetic_demo",
                note="synthetic demo annotation",
            )
        )
    s.flush()


def _run(
    s: Session, rid: str, name: str, spec: str, dv: Any, judge: JudgeRow | None = None, samples: int = SAMPLES
) -> Run:
    run = s.get(Run, rid)
    if run is not None and run.status == "succeeded":
        return run
    run = runs.create_run(
        s, run_id=rid, name=name, agent_spec=spec, dv=dv, samples=samples, seed=SEED, judge=judge, queue=False
    )
    runs.execute_run(s, run)
    s.commit()
    log.info("seeded run %s (%s)", rid, run.summary.get("task_success", {}).get("rate"))
    return run


def seed_runs(s: Session, cat: dict[str, Any], strict: JudgeRow, lenient: JudgeRow) -> dict[str, Run]:
    d = cat["datasets"]
    out: dict[str, Run] = {}
    for v in ("v1", "v2"):
        out[f"support-{v}"] = _run(
            s, f"demo-support-{v}", f"Support {v} · synthetic demo", f"support:{v}", d["support/v1"]
        )
    for v in ("v1", "v2"):
        out[f"research-{v}"] = _run(
            s, f"demo-research-{v}", f"Research {v} · synthetic demo", f"research:{v}", d["research/v1"], strict
        )
    for v in ("v1", "v2"):
        out[f"research-lenient-{v}"] = _run(
            s,
            f"demo-research-lenient-{v}",
            f"Research {v} · lenient judge (diagnostic)",
            f"research:{v}",
            d["research/v1"],
            lenient,
        )
    for v in ("v1", "v2"):
        out[f"coding-{v}"] = _run(s, f"demo-coding-{v}", f"Coding {v} · synthetic demo", f"coding:{v}", d["coding/v1"])
    for v in ("v1", "v2"):
        out[f"redteam-{v}"] = _run(
            s, f"demo-redteam-{v}", f"Red team {v} · synthetic demo", f"redteam:{v}", d["redteam/v1"]
        )
    out["support-v2-draftds"] = _run(
        s, "demo-support-v2-draftds", "Support v2 on DRAFT dataset v2 · synthetic demo", "support:v2", d["support/v2"]
    )
    return out


def seed_comparisons(s: Session, r: dict[str, Run]) -> None:
    if (s.scalar(select(func.count(Comparison.id))) or 0) > 0:
        return
    plan = [  # order matters: the LAST gate decision is the "latest" shown on the CI page = the headline support story
        ("Research v1 → v2 (lenient judge, diagnostic)", r["research-lenient-v1"], r["research-lenient-v2"], "demo-15"),
        ("Coding v1 → v2", r["coding-v1"], r["coding-v2"], "demo-20"),
        ("Support v1 vs v2 on a DIFFERENT dataset version", r["support-v1"], r["support-v2-draftds"], "demo-20"),
        ("Support v1 → v2 (production policy, min 50 cases)", r["support-v1"], r["support-v2"], "production"),
        ("Red team v1 → v2", r["redteam-v1"], r["redteam-v2"], "demo-10"),
        ("Research v1 → v2", r["research-v1"], r["research-v2"], "demo-15"),
        ("Support v1 → v2", r["support-v1"], r["support-v2"], "demo-20"),
    ]
    for name, b, c, pol in plan:
        comp = comparisons.create_comparison(s, b.id, c.id, mode="strict", policy_name=pol, name=name)
        comparisons.create_gate(s, comp, release=True)
    s.commit()


def seed_distilled(s: Session, r: dict[str, Run]) -> None:
    if (s.scalar(select(func.count(DistilledCandidate.id))) or 0) > 0:
        return
    picks = [
        ("demo-support-v2", "sup-17-address-unit-apt", False),
        ("demo-support-v1", "sup-02-refund-final-sale", False),
    ]
    for run_id, case_id, ok in picks:
        smp = s.scalar(
            select(Sample).where(Sample.run_id == run_id, Sample.case_id == case_id, Sample.sample_index == 0)
        )
        row = s.scalar(
            select(EvalCase)
            .join(Run, Run.dataset_version_id == EvalCase.dataset_version_id)
            .where(Run.id == run_id, EvalCase.case_id == case_id)
        )
        if smp is None or row is None:
            continue
        from evalcore.models import AgentResult
        from evalcore.redaction import Redactor

        cand = distill_case(Case.model_validate(row.definition), AgentResult.model_validate(smp.result), run_id, 0, ok)
        s.add(DistilledCandidate(source_sample_id=smp.id, case=Redactor().apply(cand), status="candidate"))
    s.commit()


def seed_all(s: Session) -> dict[str, Any]:
    cat = seed_catalog(s)
    s.commit()
    strict, lenient, _ = seed_calibration(s, cat["cset"])
    seed_annotations(s, cat["cset"])
    s.commit()
    r = seed_runs(s, cat, strict, lenient)
    seed_comparisons(s, r)
    seed_distilled(s, r)
    from . import experiments  # published REAL live measurements (not synthetic); idempotent

    experiments.import_experiment(s)
    s.commit()
    return {"runs": len(r), "comparisons": s.scalar(select(func.count(Comparison.id)))}
